-- ============================================================================
-- prism_degree_days: PRISM Congressional District Weather & Degree Days
-- Source: PRISM Climate Group (Oregon State University) daily 4km rasters
-- Generated by: data/prism.R via terra zonal extraction on CD shapefiles
-- ============================================================================

DROP TABLE IF EXISTS prism_degree_days;

CREATE TABLE prism_degree_days (
    year INTEGER NOT NULL,
    congress INTEGER NOT NULL,
    state_code TEXT NOT NULL,
    district_number INTEGER NOT NULL DEFAULT 0,
    mean_temp_f REAL,
    cdd REAL,
    hdd REAL,
    PRIMARY KEY (year, state_code, district_number),
    FOREIGN KEY (state_code) REFERENCES states(state_code)
);

CREATE INDEX IF NOT EXISTS idx_prism_dd_cong ON prism_degree_days(congress, state_code, district_number);
CREATE INDEX IF NOT EXISTS idx_prism_dd_year ON prism_degree_days(year);
